package com.smartlibrary.algorithms.parallel;import java.util.concurrent.*;import java.util.*;
public final class ParallelPrefixSum {private ParallelPrefixSum(){}public static long[] sequential(int[] a){long[] o=new long[a.length];long s=0;for(int i=0;i<a.length;i++)o[i]=s+=a[i];return o;}public static long[] parallel(int[] a){if(a.length<2)return sequential(a);int threads=Math.max(1,Math.min(Runtime.getRuntime().availableProcessors(),a.length));int chunk=(a.length+threads-1)/threads;long[][] local=new long[threads][];long[] sums=new long[threads];ExecutorService ex=Executors.newFixedThreadPool(threads);try{List<Future<?>> fs=new ArrayList<>();for(int t=0;t<threads;t++){final int id=t,lo=t*chunk,hi=Math.min(a.length,(t+1)*chunk);if(lo>=hi)continue;fs.add(ex.submit(()->{local[id]=new long[hi-lo];long s=0;for(int i=lo;i<hi;i++)local[id][i-lo]=s+=a[i];sums[id]=s;}));}for(Future<?> f:fs)f.get();long offset=0;for(int t=0;t<threads;t++){long[] l=local[t];if(l!=null){for(int j=0;j<l.length;j++)l[j]+=offset;offset+=sums[t];}}long[] out=new long[a.length];for(int t=0;t<threads;t++)if(local[t]!=null)System.arraycopy(local[t],0,out,t*chunk,local[t].length);return out;}catch(Exception e){throw new IllegalStateException("Parallel prefix sum failed",e);}finally{ex.shutdown();}}}
